 "content": "def transform(grid):
    """Extend each cross along its row and column; other crosses stop rays."""
    h, w = len(grid), len(grid[0])
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3}
    crosses = []
    for r in range(h):
        for c in range(w):
            arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
            if all(0 <= y < h and 0 <= x < w and grid[y][x] == 3 for y, x in arms):
                crosses.append((r, c, grid[r][c], arms))

    out = [row[:] for row in grid]
    # Horizontal rays first, then vertical rays, so vertical colors win at
    # crossings of extended lines. A foreign original nonzero cell blocks a ray.
    for r, c, color, own_arms in crosses:
        for dc in (-1, 1):
            x = c
            while 0 <= x < w:
                if grid[r][x] != 0 and (r, x) not in own_arms and (r, x) != (r, c):
                    break
                out[r][x] = color
                x += dc
    for r, c, color, own_arms in crosses:
        for dr in (-1, 1):
            y = r
            while 0 <= y < h:
                if grid[y][c] != 0 and (y, c) not in own_arms and (y, c) != (r, c):
                    break
                out[y][c] = color
                y += dr
    # The 3s are fixed markers and remain visible over every extended ray.
    for r, c in markers:
        out[r][c] = 3
    return out
