                crosses.append((r, c, grid[r][c], arms))

    out = [row[:] for row in grid]

    def paint(r, c, color, arms, horizontal):
        # A zero-centered cross erases its complete axis (while leaving 3s).
        if color == 0:
            if horizontal:
                for x in range(w):
                    if grid[r][x] != 3:
                        out[r][x] = 0
            else:
                for y in range(h):
                    if grid[y][c] != 3:
