                if grid[y][x] == 3 and (y, x) not in arms:
                    break
                if grid[y][x] != 3:
                    out[y][x] = color
                k += sign

    # Horizontal passes precede vertical passes; later lines overwrite earlier
    # colors at intersections. Original 3 marker cells are restored at the end.
    for r, c, color, arms in crosses:
        paint(r, c, color, arms, True)
    for r, c, color, arms in crosses:
        paint(r, c, color, arms, False)
